package net.officefloor.hq.app.person;

/** A validated hold request: whether the person is to be held (false: released). */
public record HoldInput(boolean held) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Puts the person on hold, or takes them off it. */
public class ApplyHold {
    public void apply(@Val HoldInput input, @Val Person person, PersonRepository repository) {
        person.setHeld(input.held());
        repository.saveAndFlush(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads from the body whether the person is to be held (true) or released (false). */
public class ValidateHold {

    public record HoldRequest(Boolean held) {
    }

    public void validate(@RequestBody(required = false) HoldRequest request, Out<HoldInput> body)
            throws InvalidPersonException {
        if (request == null || request.held() == null) {
            throw new InvalidPersonException("Say whether the person is held.");
        }
        body.set(new HoldInput(request.held()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the hold or the release, once it is saved. */
public class AuditPersonHeld {
    public void audit(@Val Person person, @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        audit.record((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.getSheetId()
                + " by=" + AuditUser.decode(user) + " name=" + person.getName());
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;

/** A person on a sheet: a name and a grade (A, B or C), the date they are retired from (null: not retired),
 *  and whether they are on hold. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false)
    private String grade;

    /** Raised on every save; an edit naming an older version is refused. */
    @Version
    @Column(nullable = false)
    private long version;

    /** Set: the person counts as retired at once, whatever the date; claims dated after it are refused. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Set: their OPEN and PENDING claims count in no live total; their SETTLED claims still count. */
    @Column(nullable = false)
    private boolean held;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getGrade() {
        return grade;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    public long getVersion() {
        return version;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }

    /** Whether a claim on this date is refused: it is after their retirement date. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.statement.Statement;

/** A person as the screen shows them: their grade in force on the sheet's today, and every grade they were given
 *  with its from-date (null for the first, which applies from the beginning of time), with their statement count
 *  and their last statement's due-total and date (null with none), and the date they are retired from (null: not
 *  retired), and whether they are on hold, and the ids of their patrons in the order they were named. */
public record PersonResponse(long id, String name, String grade, List<DatedGrade> grades, long version,
        int statementCount, String statedTotal, String statementDate, String retiredFrom, boolean held,
        List<Long> patronIds) {

    /** A grade from a date on (null: from the beginning of time). */
    public record DatedGrade(String grade, String from) {
    }

    /** @param statements the person's statements, oldest first.
     *  @param patrons the person's patrons, in the order they were named.
     *  @param grades the person's grades over time.
     *  @param today the sheet's today. */
    public static PersonResponse from(Person person, List<Statement> statements, List<Patron> patrons,
            PersonGrades grades, LocalDate today) {
        Statement last = statements.isEmpty() ? null : statements.get(statements.size() - 1);
        List<DatedGrade> dated = new ArrayList<>();
        dated.add(new DatedGrade(grades.first(), null));
        grades.dated().forEach(g -> dated.add(new DatedGrade(g.getGrade(), g.getFromDate().toString())));
        return new PersonResponse(person.getId(), person.getName(), grades.on(today), dated, person.getVersion(),
                statements.size(), last == null ? null : last.getDueTotal(),
                last == null ? null : last.getTakenOn().toString(),
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(), person.isHeld(),
                patrons.stream().map(Patron::getPatronId).toList());
    }
}
